f_Na_down = sel
  case Q_blood > 0{L_per_s}: Q_blood * c_Na__up/volume;
  case Q_blood < 0{L_per_s}: Q_blood * c_Na__down/volume;
  otherwise: 0{mM_per_s};
endsel;

